import{_ as t,o as l,c as s,a2 as i}from"./chunks/framework.DxR7mb1F.js";const e="/bluebook/assets/aihot-install.DDhhx19n.png",n="/bluebook/assets/aihot-openai-result.DVFsL6o-.png",d="/bluebook/assets/aihot-daily-report.CjG7nigL.png",A=JSON.parse('{"title":"【示例】用 WorkBuddy 自动整理每日 AI 资讯","description":"AI 资讯更新很快，同一事件经常出现在多个媒体和信息源中。逐个网站浏览不仅耗时，也容易错过模型发布、产品更新、开源项目和行业变化。 这个案例适合需要持续关注 AI 行业的产品、研发、运营、投资和内容团队。我们希望把“到处找新闻”变成一次可以重复执行的 WorkBuddy 任务。","frontmatter":{"title":"【示例】用 WorkBuddy 自动整理每日 AI 资讯","summary":"安装 AIHot Skill，查询近期 AI 动态，并把分散的信息整理成带来源链接的每日热点报告。","author":"WorkBuddy Guide 编辑组","date":"2026-07-13","category":"资讯整合","difficulty":"入门","aside":false,"outline":false,"skills":["AIHot"],"tags":["AI 资讯","AIHot","热点日报","Skill 安装"]},"headers":[],"relativePath":"cases/submissions/daily-ai-news/index.md","filePath":"cases/submissions/daily-ai-news/index.md","lastUpdated":1786934056000}'),o={name:"cases/submissions/daily-ai-news/index.md"};function p(r,a,h,c,u,k){return l(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="【示例】用-workbuddy-自动整理每日-ai-资讯" tabindex="-1">【示例】用 WorkBuddy 自动整理每日 AI 资讯 <a class="header-anchor" href="#【示例】用-workbuddy-自动整理每日-ai-资讯" aria-label="Permalink to &quot;【示例】用 WorkBuddy 自动整理每日 AI 资讯&quot;">​</a></h1><h2 id="场景描述" tabindex="-1">场景描述 <a class="header-anchor" href="#场景描述" aria-label="Permalink to &quot;场景描述&quot;">​</a></h2><p>AI 资讯更新很快，同一事件经常出现在多个媒体和信息源中。逐个网站浏览不仅耗时，也容易错过模型发布、产品更新、开源项目和行业变化。</p><p>这个案例适合需要持续关注 AI 行业的产品、研发、运营、投资和内容团队。我们希望把“到处找新闻”变成一次可以重复执行的 WorkBuddy 任务。</p><h2 id="想要完成的任务" tabindex="-1">想要完成的任务 <a class="header-anchor" href="#想要完成的任务" aria-label="Permalink to &quot;想要完成的任务&quot;">​</a></h2><p>完成后，WorkBuddy 应当能够：</p><ol><li>查询指定时间范围内的 AI 行业动态。</li><li>按公司、模型、产品或主题筛选内容。</li><li>为每条信息保留标题、摘要、发布时间和来源链接。</li><li>把大量候选信息整理成更容易阅读的热点报告。</li><li>根据任务要求重点关注大模型、产品、开源项目或论文等方向。</li></ol><h2 id="aihot-skill-能做什么" tabindex="-1">AIHot Skill 能做什么 <a class="header-anchor" href="#aihot-skill-能做什么" aria-label="Permalink to &quot;AIHot Skill 能做什么&quot;">​</a></h2><p>AIHot 是面向 AI 动态的信息类 Skill，适合查询和整理模型、产品、行业、论文与开源项目等方向的近期内容。它可以作为 WorkBuddy 的现成信息源，根据你的任务描述返回相关资讯和原始链接。</p><table tabindex="0"><thead><tr><th>用法</th><th>任务示例</th><th>适合谁</th></tr></thead><tbody><tr><td>公司动态追踪</td><td>最近 7 天 OpenAI 发布了什么</td><td>产品、研发、投资</td></tr><tr><td>每日热点整理</td><td>总结今日 AI 大模型热点</td><td>AI 团队、内容团队</td></tr><tr><td>专题检索</td><td>查找最近一周多模态模型相关动态</td><td>研究、产品规划</td></tr><tr><td>来源补充</td><td>给每条结论保留原始报道链接</td><td>需要进一步核查的读者</td></tr></tbody></table><p>AIHot 负责提供和检索候选资讯；哪些内容值得重点关注、怎样分类和以什么格式输出，由你写给 WorkBuddy 的任务描述决定。</p><h2 id="安装前准备" tabindex="-1">安装前准备 <a class="header-anchor" href="#安装前准备" aria-label="Permalink to &quot;安装前准备&quot;">​</a></h2><ul><li>已经可以正常使用 WorkBuddy。</li><li>WorkBuddy 可以访问外部网页。</li><li>AIHot Skill 地址：<code>https://aihot.virxact.com/aihot-skill/</code></li></ul><p>AIHot 来自外部地址。安装前应查看来源域名和 Skill 内容，并让 WorkBuddy 先执行安全检查。不要安装来源不明、要求异常权限或包含可疑脚本的 Skill。</p><h2 id="在-workbuddy-中安装-aihot-skill" tabindex="-1">在 WorkBuddy 中安装 AIHot Skill <a class="header-anchor" href="#在-workbuddy-中安装-aihot-skill" aria-label="Permalink to &quot;在 WorkBuddy 中安装 AIHot Skill&quot;">​</a></h2><p>打开一个新的 WorkBuddy 任务，直接输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我安装这个 skill：https://aihot.virxact.com/aihot-skill/</span></span></code></pre></div><p>WorkBuddy 会先获取 Skill 内容，并调用 Skill 安全检查流程。确认来源、权限和将要执行的内容没有异常后，再继续安装。</p><p><img src="'+e+`" alt="WorkBuddy 获取 AIHot Skill 并执行安全检查" loading="lazy"></p><p>安装完成后，可以继续问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请告诉我 AIHot Skill 已经安装到哪里、它能完成哪些任务，以及调用时是否需要额外账号或权限。</span></span></code></pre></div><p>这一步可以帮助你确认 Skill 是否真的可用，而不是只看到安装任务结束。</p><h2 id="任务一-查询最近-openai-动态" tabindex="-1">任务一：查询最近 OpenAI 动态 <a class="header-anchor" href="#任务一-查询最近-openai-动态" aria-label="Permalink to &quot;任务一：查询最近 OpenAI 动态&quot;">​</a></h2><p>最简单的任务描述是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请看一下最近 OpenAI 发布了什么新东西。</span></span></code></pre></div><p>为了让结果更稳定、方便核查，推荐写得更明确：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 AIHot Skill 查询最近 7 天与 OpenAI 相关的动态。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 优先整理 OpenAI 官方发布、模型与产品更新、API 变化和重要行业动态；</span></span>
<span class="line"><span>2. 合并明显重复的同一事件；</span></span>
<span class="line"><span>3. 每条内容包含标题、发布时间、两句话摘要和原始来源链接；</span></span>
<span class="line"><span>4. 按“官方动态、产品与模型、行业影响”分类；</span></span>
<span class="line"><span>5. 不确定的信息请明确标记，不要补写没有来源支持的结论。</span></span></code></pre></div><p>实际运行后，WorkBuddy 返回了最近 7 天的 OpenAI 相关内容，并为每条资讯保留标题、时间、摘要和 AIHot 原始链接：</p><p><img src="`+n+`" alt="AIHot 查询最近 7 天 OpenAI 动态的结果" loading="lazy"></p><h2 id="任务二-生成今日-ai-大模型热点总结" tabindex="-1">任务二：生成今日 AI 大模型热点总结 <a class="header-anchor" href="#任务二-生成今日-ai-大模型热点总结" aria-label="Permalink to &quot;任务二：生成今日 AI 大模型热点总结&quot;">​</a></h2><p>如果希望得到一份更接近日报的结果，可以输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 AIHot Skill 总结今天的 AI 热点新闻，重点关注 AI 大模型方向。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按下面结构输出：</span></span>
<span class="line"><span>1. 今日最热：列出最值得关注的 3 条动态；</span></span>
<span class="line"><span>2. 大模型新发布：整理最近 7 天值得关注的模型、产品和开源项目；</span></span>
<span class="line"><span>3. 每条包含一句话摘要、为什么值得关注和来源链接；</span></span>
<span class="line"><span>4. 合并重复报道，并注明有多少个信息源在报道同一事件；</span></span>
<span class="line"><span>5. 最后用一句话总结今天的大模型行业主线。</span></span></code></pre></div><p>实际结果按照热点和大模型方向进行了整理，保留了具体来源链接，并给出一句话结论：</p><p><img src="`+d+'" alt="AIHot 生成今日 AI 大模型热点总结" loading="lazy"></p><h2 id="怎样把任务描述写得更好" tabindex="-1">怎样把任务描述写得更好 <a class="header-anchor" href="#怎样把任务描述写得更好" aria-label="Permalink to &quot;怎样把任务描述写得更好&quot;">​</a></h2><p>一个稳定的 AIHot 任务描述，至少应该明确四件事：</p><table tabindex="0"><thead><tr><th>要素</th><th>写法示例</th></tr></thead><tbody><tr><td>时间范围</td><td>今天、最近 24 小时、最近 7 天</td></tr><tr><td>关注主题</td><td>OpenAI、大模型、多模态、AI Agent、开源项目</td></tr><tr><td>筛选标准</td><td>只保留重要更新、合并重复事件、优先官方来源</td></tr><tr><td>输出格式</td><td>标题、摘要、时间、影响判断、来源链接</td></tr></tbody></table><p>如果只说“总结 AI 新闻”，WorkBuddy 仍然可以执行，但结果的数量、范围和格式不够稳定。任务描述越明确，输出越容易复用和验收。</p><h2 id="最终效果" tabindex="-1">最终效果 <a class="header-anchor" href="#最终效果" aria-label="Permalink to &quot;最终效果&quot;">​</a></h2><p>通过 AIHot Skill，WorkBuddy 把分散的 AI 资讯整理成了两类可以直接阅读的结果：</p><ul><li>围绕特定公司或主题的近期动态列表。</li><li>经过筛选、分类和去重的 AI 热点总结。</li></ul><p>每条信息都保留来源链接，读者可以继续打开原文核查，而不是只依赖模型生成的摘要。</p><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ul><li>AIHot Skill 已成功安装，并能在新任务中被调用。</li><li>查询结果符合任务指定的时间范围和主题。</li><li>每条重要资讯都保留了可以继续访问的来源链接。</li><li>相同事件不会被当作多条重点新闻重复呈现。</li><li>摘要没有加入来源无法支持的数字和结论。</li><li>热点报告的分类与任务描述一致。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="安装后没有调用-aihot" tabindex="-1">安装后没有调用 AIHot <a class="header-anchor" href="#安装后没有调用-aihot" aria-label="Permalink to &quot;安装后没有调用 AIHot&quot;">​</a></h3><p>在任务中明确写出“使用 AIHot Skill”，并让 WorkBuddy 说明它实际调用了哪个 Skill。如果仍然不可用，检查 Skill 是否安装成功以及当前工作区是否能看到它。</p><h3 id="返回的信息太多" tabindex="-1">返回的信息太多 <a class="header-anchor" href="#返回的信息太多" aria-label="Permalink to &quot;返回的信息太多&quot;">​</a></h3><p>缩短时间范围，限定公司或主题，并明确只保留 5～8 条最重要内容。</p><h3 id="结果看起来像普通摘要" tabindex="-1">结果看起来像普通摘要 <a class="header-anchor" href="#结果看起来像普通摘要" aria-label="Permalink to &quot;结果看起来像普通摘要&quot;">​</a></h3><p>要求保留发布时间、来源名称和原始链接，并明确写出分类、去重和影响判断规则。</p><h2 id="安全与限制" tabindex="-1">安全与限制 <a class="header-anchor" href="#安全与限制" aria-label="Permalink to &quot;安全与限制&quot;">​</a></h2><ul><li>AIHot 是资讯来源，不代表所有内容都已经完成事实核查。</li><li>对重要结论，应继续打开原始链接，优先核对官方来源。</li><li>新闻内容会随时间变化，相同任务在不同日期得到的结果也会不同。</li><li>安装外部 Skill 前应检查来源、权限和脚本内容。</li><li>不要把未经核实的热点摘要直接用于正式对外发布。</li></ul><h2 id="可以怎样复用" tabindex="-1">可以怎样复用 <a class="header-anchor" href="#可以怎样复用" aria-label="Permalink to &quot;可以怎样复用&quot;">​</a></h2><p>把任务中的主题替换掉，就可以快速得到不同方向的资讯报告，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 AIHot Skill 查询最近 7 天 AI Agent 相关动态，重点关注新产品、开源框架和企业落地案例。每条保留来源链接，最后总结 3 个值得团队继续研究的方向。</span></span></code></pre></div><p>也可以在确认单次任务稳定后，再结合 WorkBuddy 自动化任务，把相同提示词设置为每日或每周重复执行。自动化属于后续扩展，这个 Case 首先确保 AIHot 的安装、调用和输出可以独立跑通。</p>',57)])])}const I=t(o,[["render",p]]);export{A as __pageData,I as default};
